/* From Uiverse.io by danilppzz  - Tags: simple, black, button, dark, hoverme */
.__UIV_SCOPE__ .button {
  background-color: #292929;
  border: 1px solid #3e3e3e;
  border-radius: 8px;
  color: #fff;
  padding: 14px 24px;
  text-decoration: none;
  font-size: 16px;
  margin: 12px 14px;
  cursor: pointer;
}

.__UIV_SCOPE__ .button:hover {
  border: 1px solid #fff;
}
